function NotificationsScreen({ navigate, onBack }: NativeScreenProps) { const session = useSession(); const older = useRef<{ userId: string | undefined; items: NotificationDTO[]; nextBefore: string | null }>({ userId: session.user?.id, items: [], nextBefore: null }); const r = useResource(async () => { if (older.current.userId !== session.user?.id) older.current = { userId: session.user?.id, items: [], nextBefore: null }; const latest = await api.notifications(); const previous = older.current; return { items: [...latest.items, ...previous.items.filter(item => !latest.items.some(newest => newest.id === item.id))], nextBefore: previous.items.length ? previous.nextBefore : latest.nextBefore }; }, 'notifications', { user: true }); const a = useAction(r.reload); const [moreBusy, setMoreBusy] = useState(false); const [moreError, setMoreError] = useState<string | null>(null); async function loadMore() { const before = r.data?.nextBefore; if (!before || moreBusy) return; setMoreBusy(true); setMoreError(null); try { const next = await request<{ items: NotificationDTO[]; nextBefore: string | null }>(`/notifications?before=${encodeURIComponent(before)}`); older.current = { userId: session.user?.id, items: [...older.current.items, ...next.items.filter(item => !older.current.items.some(existing => existing.id === item.id))], nextBefore: next.nextBefore }; r.setData(current => current ? { items: [...current.items, ...next.items.filter(item => !current.items.some(existing => existing.id === item.id))], nextBefore: next.nextBefore } : next); } catch (cause) { setMoreError(cause instanceof Error ? cause.message : 'Não foi possível carregar mais notificações.'); } finally { setMoreBusy(false); } } function open(href: string) { const event = /^\/eventos\/([^/]+)/.exec(href), room = /^\/salas\/([^/]+)/.exec(href); if (event) navigate({ name: 'event', id: event[1] }); else if (room) navigate({ name: 'room', id: room[1] }); else if (href.startsWith('/admin')) navigate({ name: 'admin' }); else navigate({ name: 'activity' }); } return <Screen title="Notificações" onBack={onBack}><Feedback {...a} /><Button title="Marcar todas como lidas" secondary busy={a.busy} onPress={() => void a.run(() => (async () => { await api.readAllNotifications(); older.current.items = older.current.items.map(item => ({ ...item, readAt: new Date().toISOString() })); })())} />{(r.loading && !r.data) || r.error ? <State loading={r.loading} error={r.error} retry={r.reload} /> : r.data?.items.length ? r.data.items.map(v => <Pressable key={v.id} accessibilityRole="button" onPress={() => void a.run(async () => { await api.readNotification(v.id); older.current.items = older.current.items.map(item => item.id === v.id ? { ...item, readAt: new Date().toISOString() } : item); open(v.href); })}><Card><Label bold={!v.readAt}>{v.title}</Label><Label>{v.message}</Label><Label muted size={12}>{new Date(v.createdAt).toLocaleString('pt-BR')}</Label></Card></Pressable>) : <State empty="Você está em dia. Nenhuma notificação por enquanto." />}<Feedback error={moreError} />{r.data?.nextBefore && <Button title="Carregar mais notificações" secondary busy={moreBusy} onPress={() => { void loadMore(); }} />}</Screen>; }
