  return <Screen title="Revisão de eventos" subtitle="Selecione eventos para moderar ou excluir com segurança." onBack={onBack}><Feedback {...a} /><Input label="Buscar evento ou endereço" value={search} onChangeText={setSearch} /><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 8 }}>{[{ value: '', label: 'Todos' }, { value: 'PENDING', label: 'Em análise' }, { value: 'CHANGES_REQUESTED', label: 'Correções' }, { value: 'PUBLISHED', label: 'Publicados' }, { value: 'CANCELLED', label: 'Cancelados' }, { value: 'ENDED', label: 'Encerrados' }].map(item => <Button key={item.value} title={`${status === item.value ? '✓ ' : ''}${item.label}`} secondary onPress={() => setStatus(item.value)} />)}</ScrollView><Input label="Orientação para o organizador" value={note} onChangeText={setNote} multiline />{selectedIds.length > 0 && <Card><Label bold>{selectedIds.length} selecionado(s)</Label><Button title="Aprovar selecionados em análise" busy={a.busy} disabled={!selectedIds.some(id => r.data?.some(event => event.id === id && event.status === 'PENDING'))} onPress={() => { const ids = selectedIds.filter(id => r.data?.some(event => event.id === id && event.status === 'PENDING')); void a.run(async () => { await request('/admin/events/validate', { method: 'POST', body: { ids } }); setSelected([]); }, 'Publicação aprovada.'); }} /><Button title="Excluir selecionados" secondary busy={a.busy} onPress={remove} /><Button title="Limpar seleção" secondary disabled={a.busy} onPress={() => setSelected([])} /></Card>}{(r.loading && !r.data) || r.error ? <State loading={r.loading} error={r.error} retry={r.reload} /> : <><Label muted size={13}>{visible.length} evento(s) encontrados</Label><Button title="Selecionar todos os resultados" secondary disabled={!visible.length || a.busy} onPress={() => setSelected(current => [...new Set([...current, ...visible.map(event => event.id)])])} />{visible.map(e => <Card key={e.id}><Pressable accessibilityRole="checkbox" accessibilityState={{ checked: selectedIds.includes(e.id), disabled: a.busy }} accessibilityLabel={`Selecionar ${e.nome}`} disabled={a.busy} onPress={() => toggle(e.id)} style={{ minHeight: 48, justifyContent: 'center' }}><Label bold size={18}>{selectedIds.includes(e.id) ? '☑' : '□'} {e.nome}</Label></Pressable><Label muted>{e.status} · {e.user?.name}</Label><Label>{e.endereco}</Label>{e.reviewNote && <Label muted>Orientação: {e.reviewNote}</Label>}<Button title="Detalhes" secondary onPress={() => navigate({ name: 'event', id: e.id })} />{e.status === 'PENDING' && <><Button title="Aprovar publicação" busy={a.busy} onPress={() => void a.run(() => request('/admin/events/validate', { method: 'POST', body: { ids: [e.id] } }))} /><Button title="Solicitar correções" secondary disabled={note.trim().length < 5} busy={a.busy} onPress={() => void a.run(() => request(`/admin/events/${encodeURIComponent(e.id)}/correction`, { method: 'POST', body: { reason: note } }))} /></>}</Card>)}{visible.length === 0 && <State empty="Nenhum evento corresponde aos filtros." />}</>}</Screen>;
